```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true` on every output, so a node whose notification is
/// never accepted must not produce an output at all.
const NOTIFY_ATTEMPTS: u32 = 3;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input this call received in the shared
        // store under `last-input`. This does not affect the output.
        state_rw::put("last-input", &feed_url);

        // Clock: read the wall time once.
        let seconds = wall_clock::now().seconds;

        // HTTP: one permitted fetch. A transport failure (timeout, error status,
        // oversize body) is a value and counts as zero characters fetched. A host
        // outside the allowlist traps at the boundary, which is correct: that is
        // not a failed fetch.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report what happened.
        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // `ensures notified == true`: never emit an output that violates the
        // contract. If the channel refused every attempt, trap instead
        // (panic = "abort").
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
